function editAssetSVG(asset,raw){if(asset.locked)return toast('Unlock the protected icon before editing its SVG.');const err=validateSVG(raw);if(err)return toast('SVG rejected: '+err);snapshot('Before manual SVG refinement: '+asset.label);asset.ancestry.push({timestamp:now(),action:'manual SVG edit',previous:asset.sourceSvg});asset.sourceSvg=raw;asset.manualOverride=true;asset.status='draft';asset.updated=now();record('asset.manualEdit','Manually edited SVG; detached from automatic Style DNA regeneration.',[asset.id]);render();toast('Manual SVG saved and protected from automatic regeneration.');}
function audit(){let findings=[],s=activeStyle(),bg=s.background;const add=(asset,dimension,type,severity,confidence,evidence,effect,repair)=>findings.push({id:uid('qa'),assetId:asset?.id||null,label:asset?.label||'Family',dimension,type,severity,confidence,evidence,effect,repair,at:now()});
const counts={};p.icons.forEach(a=>counts[a.concept]=(counts[a.concept]||0)+1);for(const a of p.icons){const err=validateSVG(a.sourceSvg);if(err){add(a,'Production integrity','objective failure','critical','high',err,'SVG may not be usable or safe.','Repair malformed or unsafe SVG.');continue;}const st=analyzeSvg(a.sourceSvg);if(st.viewBox!=='0 0 64 64')add(a,'Production integrity','format divergence','warning','high','viewBox is '+st.viewBox+'.','Some output sizes may be inconsistent.','Normalize viewBox after inspecting appearance.');if(a.pinned)add(a,'Lineage','intentional version pin','informational','high','This asset was excluded from a shared-rule propagation.','Its approved SVG remains unchanged as the surrounding family evolves.','Explicitly rejoin shared-rule inheritance when appropriate.');if(a.manualOverride)add(a,'Lineage','intentional exception','informational','high','Manual SVG editing detached this icon from automatic rule inheritance.','Future DNA propagation will preserve it unchanged.','Rejoin manually if intended.');if(a.exception)add(a,'Intentional exception','intentional exception','informational','high',a.exception.reason,'This deviation is documented and protected.','Revisit only if surrounding style or intent changes.');if(!a.semanticReviewed)add(a,'Semantic clarity','uncertain interpretation','uncertain','high','No human semantic review recorded.','Visual appearance does not prove the symbol conveys the intended concept.','Inspect the icon at its target size and mark semantic review.');if(a.status!=='approved')add(a,'Approval','incomplete review','warning','high','Icon status is '+a.status+'.','The family still contains unapproved assets.','Review and approve or remove.');if(counts[a.concept]>1)add(a,'Semantic clarity','redundancy','warning','high',`Concept '${a.concept}' appears ${counts[a.concept]} times.`,'Duplicated semantics may require differentiation.','Change meaning or document legitimate alternate forms.');let sw=st.strokeWidth;if(sw&&Math.abs(sw-Number(s.strokeWidth))>1.1&&!a.manualOverride&&!a.exception)add(a,'Visual consistency','possible stroke drift','warning','medium',`Observed SVG stroke ${sw}, current shared rule ${s.strokeWidth}.`,'Visual line weight may differ from family baseline.','Preview targeted regeneration or document an exception.');}
function lum(hex){let r=[1,3,5].map(i=>parseInt(hex.slice(i,i+2),16)/255).map(v=>v<=.04045?v/12.92:Math.pow((v+.055)/1.055,2.4));return r[0]*.2126+r[1]*.7152+r[2]*.0722;}
if(/^#[\da-f]{6}$/i.test(s.strokeColor)&&/^#[\da-f]{6}$/i.test(bg)){let l1=lum(s.strokeColor),l2=lum(bg),ratio=(Math.max(l1,l2)+.05)/(Math.min(l1,l2)+.05);if(ratio<3)add(null,'Accessibility','contrast risk','warning','high',`Stroke/background contrast ratio is ${ratio.toFixed(2)}:1 against the project light test surface.`,'Thin symbols may be difficult to distinguish.','Increase contrast, weight or both; test against deployment backgrounds.');let dark=lum('#222933'),dr=(Math.max(l1,dark)+.05)/(Math.min(l1,dark)+.05);if(dr<3)add(null,'Accessibility','dark-surface contrast risk','warning','high',`Stroke/dark test surface contrast is ${dr.toFixed(2)}:1.`,'The same color may become hard to see in a dark theme.','Use a dark-mode color token or project-specific color treatment.');}
if(!p.references.length)add(null,'Provenance','insufficient source evidence','uncertain','high','No reference source supplied.','This is an original template family, not a reference-derived match.','Import sources and extract provisional DNA if matching is required.');
if(!p.calibration.approved)add(null,'Calibration','unverified readiness','warning','high','Calibration set has not been approved.','Family-wide robustness has not been reviewed.','Run and approve representative stress tests.');
if(p.references.some(x=>x.type==='raster'))add(null,'Reference Forensics','analysis limitation','informational','high','Raster analysis sampled colors only.','Stroke, geometry, and semantic resemblance were not machine-validated.','Document inferred rules with evidence manually.');
const c=p.icons.filter(x=>x.status==='approved').length;add(null,'Family coherence','overall synthesis','informational','high',`${c}/${p.icons.length} icons approved; ${findings.filter(x=>x.severity==='critical').length} critical failure(s) found in implemented checks.`, 'This is a limited heuristic summary, not a definitive aesthetic score.','Compare reference and candidate grids, inspect at 16/24/64 pixels, and document human judgments.');
p.qa={findings,lastRun:now()};record('qa.audit','Ran supported integrity, style-rule, approval, provenance, and review checks. Semantic and aesthetic judgment remain assisted.',p.icons.map(x=>x.id));render();toast(findings.length+' findings recorded; see evidence by dimension.');}
function render(){const nav=$('#nav');nav.innerHTML=STEPS.map((x,i)=>`<button class="nav ${step===i?'active':''}" data-go="${i}"><span class="num">${i}</span>${esc(x)}</button>`).join('')+`<div class="side-note">Offline and free. Your project is held in browser memory until you save a <strong>.iconkin.json</strong> file. No uploads or network requests.<br><br><span class="chip warn">Prototype, not full plugin</span></div>`;
const views=[viewOverview,viewReferences,viewDNA,viewCalibration,viewFamily,viewQA,viewArchive];$('#content').innerHTML=views[step]();renderModal();}
function title(name,sub){return `<div class="eyebrow">Step ${step} / 6</div><h2>${name}</h2><p class="sub">${sub}</p>`;}
function viewOverview(){let approved=p.icons.filter(x=>x.status==='approved').length;return `<div class="eyebrow">Working prototype · honest by design</div><h2>${esc(p.manifest.name)}</h2><p>One portable design system. Measurable evidence, editable rules, hand-reviewed meanings, deterministic SVG construction, preservation and round-trip recovery.</p><div class="columns three"><div class="pane sage"><div class="eyebrow">Sources</div><h2>${p.references.length}</h2><div class="sub">Imported references</div></div><div class="pane gold"><div class="eyebrow">Family</div><h2>${p.icons.length}</h2><div class="sub">Icons · ${approved} approved</div></div><div class="pane rose"><div class="eyebrow">Archive</div><h2>r${p.manifest.revision}</h2><div class="sub">${p.history.length} decisions recorded</div></div></div><div class="pane"><h3>End-to-end workflow</h3><div class="stack">${STEPS.slice(1).map((x,i)=>`<div class="row between"><div><span class="chip">${i+1}</span> <strong>${x}</strong></div><button class="small" data-go="${i+1}">Open →</button></div>`).join('')}</div></div><div class="pane gold"><h3>What is real in version 0.1?</h3><p><strong>Working:</strong> SVG attribute extraction, raster color sampling, rule editing/locking, small recipe-based SVG generation, local SVG editing, review and approval, basic QA, downloadable asset ZIP, complete JSON project, reopen, snapshots and restoration.</p><p><strong>Assisted:</strong> inferred visual personality, semantically correct interpretation, optical balancing, reference matching, accessibility beyond measured color contrast.</p><p><strong>Not implemented:</strong> generative image models, automated aesthetic verification, cloud synchronization, icon fonts, collaborative editing, full path manipulation, schema migration, and a ChatGPT plugin connector.</p><div class="row"><button class="primary" data-go="1">Start with references →</button><button data-act="demo">Open small example</button></div></div><div class="pane"><label for="projname">Project name</label><input id="projname" type="text" value="${esc(p.manifest.name)}" data-field="project-name"><p class="sub">Edit the name, then save a portable archive before closing the tab.</p></div>`;}
function viewReferences(){return title('Reference Forensics','Sources are evidence, not proof of intent. Import SVGs for attribute measurements; raster artwork supports palette sampling and manual interpretation.')+`<div class="pane"><div class="drop" id="dropzone"><h3>Import a reference family</h3><p class="sub">SVG, PNG, JPG, WebP · max 8 MB per file · local only</p><button class="primary" data-act="pickrefs">Choose images or SVG files</button></div>${lastReferenceImport?`<section class="import-report" role="status"><strong>Import result: ${lastReferenceImport.accepted} of ${lastReferenceImport.total} accepted</strong>${lastReferenceImport.rejected.length?`<ul>${lastReferenceImport.rejected.map(x=>`<li><strong>${esc(x.name)}</strong>: ${esc(x.reason)}</li>`).join('')}</ul>`:''}${lastReferenceImport.warnings.length?`<details><summary>Preview adjustments (${lastReferenceImport.warnings.length})</summary><ul>${lastReferenceImport.warnings.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></details>`:''} </section>`:''}<div class="row between" style="margin-top:15px"><span class="sub">${p.references.length} reference(s)</span><button data-act="extract" ${!p.references.length?'disabled':''}>Extract measurable Style DNA →</button></div></div><div class="refgrid">${p.references.map(r=>`<div class="refcard"><img alt="${esc(r.name)}" src="${esc(r.data)}"><div class="bold">${esc(r.name)}</div><div class="tiny muted">${r.type.toUpperCase()} · ${Math.round(r.size/1024)} KB</div><div class="tiny">${r.type==='svg'?`Shapes: ${r.stats.shapeCount} · stroke ${esc(r.stats.strokeWidth??'unknown')}`:'Palette samples: '+(r.stats.palette||[]).length}</div>${r.stats.palette?`<div class="row">${r.stats.palette.slice(0,5).map(c=>`<span title="${c}" style="height:18px;width:18px;background:${c};border-radius:4px;border:1px solid #ccc"></span>`).join('')}</div>`:''}<label>Attribution / license note</label><textarea rows="2" data-refnote="${r.id}">${esc(r.attribution)}</textarea><button class="small" data-act="removeref" data-id="${r.id}">Remove</button></div>`).join('')}</div><div class="pane"><h3>Evidence boundary</h3><p class="sub">SVG: reports explicitly encoded shapes, viewBox, selected colors and stroke properties. Raster: estimates coarse colors only. Inference about original design principles, source attribution, purpose and symbolism requires human judgment and remains provisional.</p></div>`;}
function ruleControl(k,r){let meta=RULE_META[k]||[k,'text','Imported extension rule; interpreted only as text'],type=meta[1],locked=r.status==='locked';let input=type==='number'?`<input type="number" min="0" max="18" step="0.25" data-rule="${k}" value="${esc(r.value)}" ${locked?'disabled':''}>`:type==='color'?`<input type="color" data-rule="${k}" value="${esc(colorText(r.value))}" ${locked?'disabled':''}>`:type==='select'?`<select data-rule="${k}" ${locked?'disabled':''}>${['round','butt','square','miter','bevel'].map(x=>`<option ${x===r.value?'selected':''}>${x}</option>`).join('')}</select>`:`<input type="text" data-rule="${k}" value="${esc(r.value)}" ${locked?'disabled':''}>`;
return `<div class="rule ${locked?'locked':''}"><div class="row between"><strong>${esc(meta[0])}</strong><span class="chip ${ruleStatus(r.status)}">${esc(r.status)}</span></div><div class="sub tiny">${esc(meta[2])}</div>${input}<div class="tiny muted" style="margin:8px 0">${esc(r.source)} · confidence: ${esc(r.confidence)}</div><div class="tiny">${esc(r.evidence)}</div><div class="row" style="margin-top:10px"><button class="small" data-act="rulestatus" data-id="${k}" data-value="approved" ${locked?'disabled':''}>Approve</button><button class="small" data-act="rulestatus" data-id="${k}" data-value="rejected" ${locked?'disabled':''}>Reject</button><button class="small" data-act="rulestatus" data-id="${k}" data-value="${locked?'approved':'locked'}">${locked?'Unlock':'Lock'}</button></div></div>`;}
function viewDNA(){return title('Style DNA Inspector','Rules are explicit. Their evidence, status, and inheritance are preserved. Editing shared DNA previews which icons will change before applying it.')+`<div class="helper">The extractor reads measurable SVG attributes and proposes provisional rules. Geometry, symbolism, texture and personality are initially manual interpretations, never silently presented as observed facts.</div><div class="pane"><div class="row between"><h3>Design rules</h3><button data-act="extract" ${!p.references.length?'disabled':''}>Re-extract from references</button></div><div class="rulegrid">${Object.entries(p.styleDNA.rules).map(([k,r])=>ruleControl(k,r)).join('')}</div></div><div class="pane"><h3>Optional symbolic grammar</h3><label class="toggle"><input type="checkbox" id="grammarenabled" ${p.symbolicGrammar.enabled?'checked':''}> Enable symbolic grammar records</label><label>Meanings, recurring motifs and constraints (manual in 0.1)</label><textarea id="grammarnotes">${esc(p.symbolicGrammar.notes||'')}</textarea><button data-act="savegrammar">Save grammar notes</button><p class="sub">Grammar is preserved in the archive; automatic symbol analysis is not implemented in version 0.1.</p></div>`;}
function viewCalibration(){let cs=p.calibration.concepts,variants=p.calibration.variants;return title('Calibration & falsification','Test the difficult cases first: simple, multipart, abstract, directional. The plugin recommends a set you can change. Visual and semantic readiness requires your judgment.')+`<div class="pane"><div class="row between"><h3>Proposed stress-test concepts</h3><button data-act="proposecal">Propose representative set</button></div><p class="sub">Selection challenges shape complexity and semantic abstraction. It cannot automatically infer how users interpret a symbol.</p><div class="pickgrid">${CATALOG.map(([id,n,g])=>`<label class="pick"><input type="checkbox" data-calpick="${id}" ${cs.includes(id)?'checked':''}> ${esc(n)} <span class="tiny muted">${g}</span></label>`).join('')}</div><label>Calibration observations / known edge cases</label><textarea id="calnotes">${esc(p.calibration.notes)}</textarea><div class="row" style="margin-top:10px"><button class="primary" data-act="approvecal">Approve this calibration set</button><span class="chip ${p.calibration.approved?'ok':'warn'}">${p.calibration.approved?'Approved by user':'Unapproved'}</span></div></div>${cs.length?`<div class="pane"><h3>Candidate calibration sheet</h3><p class="sub">Three deterministic recipe variants are shown. Choose one per concept; use different sizes to spot legibility and density problems.</p><div class="columns">${cs.map(c=>`<div class="refcard"><div class="bold">${esc(CATALOG_MAP[c]?.[1]||c)}</div><div class="previewtray">${['balanced','compact','expressive'].map(v=>`<div style="text-align:center"><img alt="${c} ${v}" width="70" height="70" src="${svgImg(iconSVG(c,v))}"><br><button class="small" data-act="calvariant" data-id="${c}" data-value="${v}" style="${(variants[c]||'balanced')===v?'background:#dbe9f1':''}">${v}</button></div>`).join('')}</div><div class="row"><span class="tiny">16px</span><img width="16" height="16" src="${svgImg(iconSVG(c,variants[c]||'balanced'))}"><span class="tiny">24px</span><img width="24" height="24" src="${svgImg(iconSVG(c,variants[c]||'balanced'))}"></div></div>`).join('')}</div></div>`:''}<div class="pane gold"><h3>Readiness is not automatically certified</h3><p class="sub">Approving calibration records human acceptance of representative coverage. It does not claim perceptual usability, fidelity to complex illustrations, or universal accessibility. Critical objective SVG failures are checked separately by the Consistency Lab.</p><button data-go="4">Continue to family construction →</button></div>`;}
function viewFamily(){let a=p.icons.find(x=>x.id===selected),opts=CATALOG;return title('Icon Family Board','Build real SVG assets using deterministic symbol recipes. Compare at useful sizes, inspect meaning, edit source SVG, approve or protect hand-refined work.')+`<div class="pane"><div class="row between"><h3>Concept list for next batch</h3><span class="chip">${p.icons.length} icons</span></div><div class="pickgrid">${opts.map(([id,n])=>`<label class="pick"><input type="checkbox" data-pick="${id}" ${draftSelected.includes(id)?'checked':''}> ${esc(n)}</label>`).join('')}</div><div class="row" style="margin-top:12px"><button class="primary" data-act="generate">Construct missing concepts</button><span class="sub">Existing icons are never silently overwritten.</span></div></div><div class="pane"><div class="row between"><h3>Family</h3><button class="small" data-act="audit">Run QA</button></div>${p.references.length?`<div class="row" style="margin:9px 0 14px"><span class="sub">Reference comparison:</span>${p.references.slice(0,7).map(r=>`<div style="width:61px;text-align:center"><img alt="${esc(r.name)}" src="${esc(r.data)}" style="height:52px;width:60px;object-fit:contain;background:#f5f0e6;border-radius:7px"><div class="tiny muted" style="overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${esc(r.name)}</div></div>`).join('')}</div>`:''}${p.icons.length?`<div class="icongrid">${p.icons.map(x=>`<div class="iconcard ${selected===x.id?'selected':''}" data-act="selecticon" data-id="${x.id}"><img alt="${esc(x.label)}" src="${svgImg(x.sourceSvg)}"><div class="iconname">${esc(x.label)}</div><span class="chip ${x.status==='approved'?'ok':'warn'}">${esc(x.status)}</span>${x.locked?' <span class="chip unknown">locked</span>':''}${x.pinned?' <span class="chip unknown">pinned</span>':''}</div>`).join('')}</div>`:'<p class="sub">No icons yet. Approve calibration and create a small batch.</p>'}</div>${a?viewInspector(a):''}`;}
function viewInspector(a){return `<div class="pane"><div class="row between"><h3>Inspect · ${esc(a.label)}</h3><button data-act="deselect">Close inspector</button></div><div class="columns"><div><div class="previewtray"><div class="previewtile"><img src="${svgImg(a.sourceSvg)}"><div class="tiny">64px · light</div></div><div class="previewtile dark"><img src="${svgImg(a.sourceSvg)}"><div class="tiny">64px · dark test</div></div></div><div class="row" style="margin:14px 0"><span>16px</span><img src="${svgImg(a.sourceSvg)}" height="16" width="16"><span>24px</span><img src="${svgImg(a.sourceSvg)}" height="24" width="24"><span>32px</span><img src="${svgImg(a.sourceSvg)}" height="32" width="32"></div><label>Symbolic meaning (human-reviewed)</label><input data-assetfield="meaning" data-id="${a.id}" type="text" value="${esc(a.meaning)}"><label>Notes about meaning / ambiguity</label><textarea data-assetfield="semanticNotes" data-id="${a.id}" rows="2">${esc(a.semanticNotes)}</textarea><label class="toggle"><input data-assetcheck="semanticReviewed" data-id="${a.id}" type="checkbox" ${a.semanticReviewed?'checked':''}> I inspected the meaning at intended sizes</label><label class="toggle"><input data-assetcheck="pinned" data-id="${a.id}" type="checkbox" ${a.pinned?'checked':''}> Pin current icon version</label><label class="toggle"><input data-assetcheck="locked" data-id="${a.id}" type="checkbox" ${a.locked?'checked':''}> Protect from shared-rule propagation</label><label>Intentional exception rationale (optional)</label><textarea data-assetfield="exception" data-id="${a.id}" rows="2">${esc(a.exception?.reason||'')}</textarea><div class="row"><button class="primary" data-act="approveasset" data-id="${a.id}">${a.status==='approved'?'Reaffirm approval':'Approve icon'}</button><button data-act="downloadsvg" data-id="${a.id}">Download SVG</button></div></div><div><h3>Editable construction</h3><p class="sub">Recipe: <strong>${esc(a.concept)}</strong> · Variant: ${esc(a.variant)} · Inheritance: ${a.manualOverride?'Detached/manual':'Shared Style DNA'}</p><div class="row">${['balanced','compact','expressive'].map(v=>`<button class="small" data-act="variant" data-id="${a.id}" data-value="${v}" ${a.variant===v?'style="background:#e3edf5"':''} ${a.manualOverride||a.locked?'disabled':''}>${v}</button>`).join('')}</div><label>SVG source · edit carefully</label><textarea id="svgeditor" class="svginput" spellcheck="false">${esc(a.sourceSvg)}</textarea><div class="row"><button data-act="savesvg" data-id="${a.id}" ${a.locked?'disabled':''}>Save manual SVG edit</button><button data-act="rejoin" data-id="${a.id}" ${!a.manualOverride&&!a.pinned?'disabled':''}>Rejoin rule inheritance</button></div><p class="tiny muted">Unsafe SVG elements and external resources are rejected. Editing SVG creates a protected local override. Rejoining regenerates using the current shared rules after confirmation.</p></div></div></div>`;}
function viewQA(){let findings=p.qa.findings, groups={};findings.forEach(f=>(groups[f.dimension]??=[]).push(f));return title('Consistency Lab','Evidence-based checks, not an opaque style score. Objective failures are separated from uncertain human interpretations and intentional exceptions.')+`<div class="pane"><div class="row between"><div><strong>Latest assessment</strong><p class="sub">${p.qa.lastRun?esc(p.qa.lastRun):'Not yet assessed'}</p></div><button class="primary" data-act="audit">Run checks now</button></div><div class="legend"><span class="chip bad">Critical</span><span class="chip warn">Warning</span><span class="chip unknown">Uncertain</span><span class="chip">Informational</span><span class="chip ok">Intentional exception</span></div><p class="sub">Implemented checks: SVG syntax/unsafe nodes, viewBox, partial stroke alignment, basic color contrast, concept redundancy, required reviews, provenance limitations, and approval state. Not implemented: machine-rated semantics, optical balance, perceived fidelity, full WCAG conformance, all exporter targets.</p></div>${Object.entries(groups).map(([dim,fs])=>`<div class="pane"><h3>${esc(dim)} <span class="chip">${fs.length}</span></h3>${fs.map(f=>`<div class="finding ${['critical','warning','uncertain'].includes(f.severity)?f.severity:f.type==='intentional exception'?'exception':'informational'}"><div class="row between"><strong>${esc(f.label)}</strong><span class="chip ${f.severity==='critical'?'bad':f.severity==='warning'?'warn':f.severity==='uncertain'?'unknown':f.type==='intentional exception'?'ok':''}">${esc(f.severity)}</span></div><div class="tiny muted">${esc(f.type)} · confidence: ${esc(f.confidence)}</div><p><strong>Evidence:</strong> ${esc(f.evidence)}</p><p><strong>Consequence:</strong> ${esc(f.effect)}</p><p><strong>Possible repair:</strong> ${esc(f.repair)}</p></div>`).join('')}</div>`).join('')}${!findings.length?'<div class="pane gold">Run the checks to obtain transparent, dimension-specific findings.</div>':''}`;}
function viewArchive(){return title('Living Design Archive','This portable JSON file is the authoritative project. SVG and ZIP exports are derivatives. Save it locally, reopen it, inspect history and continue editing.')+`<div class="columns"><div class="pane sage"><h3>Save & export</h3><p class="sub">A self-contained <code>.iconkin.json</code> includes original references, approved SVG source, current Style DNA, grammar, decisions, snapshots, QA and lineage.</p><div class="stack"><button class="primary" data-act="save">Save complete project JSON</button><button data-act="export">Export SVG pack ZIP + project</button><button data-act="open">Reopen a saved project</button></div></div><div class="pane gold"><h3>Validation & limitations</h3><p class="sub">The ZIP bundles SVG assets, references where available, project JSON, and a human-readable manifest. The separate free Python validator checks its structure and files.</p><button data-act="audit">Run supported validation checks</button><p class="tiny">No network or paid service is needed. To demonstrate persistence, save the JSON, close/reopen this HTML, and open the saved JSON.</p></div></div><div class="pane"><div class="row between"><h3>Recovery snapshots</h3><button data-act="snapshot">Create recovery snapshot</button></div>${p.snapshots.length?p.snapshots.slice().reverse().slice(0,15).map(s=>`<div class="row between" style="padding:9px 0;border-bottom:1px solid var(--line)"><div><strong>${esc(s.reason)}</strong><div class="tiny muted">${esc(s.timestamp)} · revision ${s.revision}</div></div><button class="small" data-act="restore" data-id="${s.id}">Preview restore</button></div>`).join(''):'<p class="sub">No snapshot yet. Major operations automatically create one.</p>'}</div><div class="pane"><h3>Audit trail · last 35 events</h3>${p.history.length?p.history.slice().reverse().slice(0,35).map(e=>`<div style="border-bottom:1px solid var(--line);padding:9px 0"><strong>${esc(e.action)}</strong><div class="tiny muted">${esc(e.timestamp)} · ${esc(e.initiator)}</div><div class="sub">${esc(e.explanation)}</div></div>`).join(''):'<p class="sub">No decisions recorded yet.</p>'}</div><div class="pane"><h3>Machine-readable project summary</h3><div class="codeblock">${esc(JSON.stringify({schema:p.schema,manifest:p.manifest,references:p.references.length,icons:p.icons.length,styleDNA:p.styleDNA.rules,symbolicGrammar:p.symbolicGrammar,qa:{findings:p.qa.findings.length,lastRun:p.qa.lastRun},history:p.history.length,snapshots:p.snapshots.length},null,2))}</div></div>`;}
function renderModal(){if(!modal){$('#modalarea').innerHTML='';return;}let html='';if(modal.type==='calibrationGate')html=`<h2>Calibration not approved</h2><p>Large-scale readiness is unverified. You can proceed as an explicitly recorded override, or inspect and approve a representative test set first.</p><div class="row"><button data-act="closemodal">Review calibration</button><button class="primary" data-act="overridecal">Generate with recorded override</button></div>`;
if(modal.type==='propagation'&&pendingRule){let {key,value,affected,approved}=pendingRule;let s=activeStyle(),after={...s,[key]:value};html=`<h2>Review shared-rule propagation</h2><p><strong>${esc(RULE_META[key][0])}:</strong> ${esc(p.styleDNA.rules[key].value)} → ${esc(value)}</p><p class="sub">Eligible inherited assets are selected by default. Locked and manually refined icons remain untouched. Unselected assets keep their existing approved SVG source.</p><div class="refgrid">${p.icons.map(a=>`<div class="refcard"><div class="bold">${esc(a.label)}</div><div class="row"><img style="width:55px;height:60px;object-fit:contain" src="${svgImg(a.sourceSvg)}"><img style="width:55px;height:60px;object-fit:contain" src="${svgImg(a.manualOverride?a.sourceSvg:iconSVG(a.concept,a.variant,after))}"></div><div class="tiny muted">Before → proposed</div><label class="tilecheck"><input type="checkbox" data-prop="${a.id}" ${approved.has(a.id)?'checked':''} ${!affected.includes(a.id)?'disabled':''}> ${!affected.includes(a.id)?'Protected / detached':'Apply'}</label></div>`).join('')}</div><div class="row" style="margin-top:18px"><button data-act="closemodal">Cancel</button><button class="primary" data-act="commitrule">Apply selected changes</button></div>`;}
if(modal.type==='restore'){const s=p.snapshots.find(x=>x.id===modal.id);html=`<h2>Restore snapshot?</h2><p>This will replace the active working copy with <strong>${esc(s?.reason||'the selected state')}</strong>. The current state is preserved as a recoverable snapshot first.</p><div class="row"><button data-act="closemodal">Cancel</button><button class="primary" data-act="commitrestore" data-id="${esc(modal.id)}">Restore</button></div>`;}
if(modal.type==='rejoin'){html=`<h2>Rejoin Style DNA?</h2><p>Regeneration will replace this manually edited SVG. A recovery snapshot preserves the previous source and it remains visible in lineage. The icon is returned to draft for review.</p><div class="row"><button data-act="closemodal">Cancel</button><button class="primary" data-act="commitrejoin" data-id="${esc(modal.id)}">Rejoin</button></div>`;}
$('#modalarea').innerHTML='<div class="modalwrap"><div class="modal">'+html+'</div></div>';}
function download(filename,contents,type='application/octet-stream'){let blob=contents instanceof Blob?contents:new Blob([contents],{type});let link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download=filename;document.body.appendChild(link);link.click();setTimeout(()=>{URL.revokeObjectURL(link.href);link.remove();},800);}
function fileSlug(s){return String(s).toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'').slice(0,55)||'icon-kin';}
function exportedProject(){let obj=clone(p);obj.manifest.exportedAt=now();return obj;}
function saveJSON(){const o=exportedProject();download(fileSlug(p.manifest.name)+'.iconkin.json',JSON.stringify(o,null,2),'application/json');toast('Saved portable JSON. Keep this file to reopen the project.');}
const CRC_TABLE=(()=>{let t=[];for(let n=0;n<256;n++){let c=n;for(let k=0;k<8;k++)c=c&1?0xedb88320^(c>>>1):c>>>1;t[n]=c>>>0;}return t;})();
function crc32(b){let c=0xffffffff;for(let x of b)c=CRC_TABLE[(c^x)&255]^(c>>>8);return(c^0xffffffff)>>>0;}
function zipBytes(entries){const enc=new TextEncoder(),local=[],central=[];let offset=0;const u16=v=>[v&255,(v>>>8)&255],u32=v=>[v&255,(v>>>8)&255,(v>>>16)&255,(v>>>24)&255];for(const [name,data] of entries){let n=enc.encode(name),b=data instanceof Uint8Array?data:enc.encode(data),crc=crc32(b),h=new Uint8Array([...u32(0x04034b50),...u16(20),...u16(0),...u16(0),...u16(0),...u16(0),...u32(crc),...u32(b.length),...u32(b.length),...u16(n.length),...u16(0),...n]);local.push(h,b);let ce=new Uint8Array([...u32(0x02014b50),...u16(20),...u16(20),...u16(0),...u16(0),...u16(0),...u16(0),...u32(crc),...u32(b.length),...u32(b.length),...u16(n.length),...u16(0),...u16(0),...u16(0),...u16(0),...u32(0),...u32(offset),...n]);central.push(ce);offset+=h.length+b.length;}let clen=central.reduce((a,b)=>a+b.length,0),end=new Uint8Array([...u32(0x06054b50),...u16(0),...u16(0),...u16(entries.length),...u16(entries.length),...u32(clen),...u32(offset),...u16(0)]);return new Blob([...local,...central,end],{type:'application/zip'});}
function exportZIP(){const bad=p.icons.find(a=>validateSVG(a.sourceSvg));if(bad)return toast('Export blocked: invalid SVG in '+bad.label);p.exports.push({timestamp:now(),type:'local-zip-prepared',revision:p.manifest.revision,assets:p.icons.map(a=>a.id),notes:'Prepared ZIP of SVGs and authoritative project JSON; ZIP CRC32 (not a trusted signature).'});record('export.prepare','Prepared portable project and SVG assets for user download.');const o=exportedProject(),entries=[['project.iconkin.json',JSON.stringify(o,null,2)],['README.txt','ICON KIN · prototype 0.1\nThe JSON project is authoritative. Assets and references are derived copies.\nOpen index.html locally and use Open project to resume.\nFor independent validation run python validate_iconkin.py project.iconkin.json\nNo generative AI or cloud processing was used.\n']];const used=new Set();p.icons.forEach((a,i)=>{let slug=fileSlug(a.label),file=`icons/${slug}-${a.id.slice(-8)}.svg`;entries.push([file,a.sourceSvg]);entries.push([file+'.asset.json',JSON.stringify({format:'iconkin.asset/0.1',projectId:p.manifest.id,projectRevision:p.manifest.revision,projectBranch:p.manifest.branch,iconId:a.id,concept:a.concept,meaning:a.meaning,iconStatus:a.status,sourceDNARevision:a.sourceDNARevision,grammarEnabled:p.symbolicGrammar.enabled,manualOverride:a.manualOverride,locked:a.locked,pinned:!!a.pinned,exception:a.exception,sourceOfTruth:'project.iconkin.json'},null,2)]);used.add(file);});p.references.forEach(r=>{if(r.type==='svg'){entries.push([`references/${r.id}.svg`,r.source]);return;}const match=r.data.match(/^data:[^;]+;base64,(.+)$/);if(match){let raw=atob(match[1]);let b=new Uint8Array(raw.length);for(let i=0;i<raw.length;i++)b[i]=raw.charCodeAt(i);let suffix=r.type==='svg'?'svg':r.mediaType==='image/png'?'png':r.mediaType==='image/webp'?'webp':'jpg';entries.push([`references/${r.id}.${suffix}`,b]);}});download(fileSlug(p.manifest.name)+'-pack.zip',zipBytes(entries),'application/zip');render();toast('ZIP download prepared with matching project and icon assets.');}
function validateImported(obj){if(!obj||obj.schema!=='iconkin.project/0.1'||!obj.manifest?.id||!obj.styleDNA?.rules||!Array.isArray(obj.icons)||!Array.isArray(obj.references)||!Array.isArray(obj.history)||!Array.isArray(obj.snapshots))throw Error('Missing required project structure or unsupported schema.');if(obj.icons.length>2000||obj.references.length>500)throw Error('Project exceeds prototype capacity limits.');const safeId=id=>typeof id==='string'&&/^[a-zA-Z0-9_-]{1,100}$/.test(id);if(!safeId(obj.manifest.id))throw Error('Invalid project ID.');if(Object.keys(obj.styleDNA.rules).some(k=>!safeId(k)))throw Error('Unsafe rule key.');for(const a of obj.icons){if(!safeId(a.id)||validateSVG(a.sourceSvg))throw Error('Invalid SVG asset or identifier: '+(a.label||'unnamed'));}for(const r of obj.references){if(!safeId(r.id))throw Error('Invalid reference ID.');if(!r.data?.startsWith('data:image/'))throw Error('Reference source missing or unsupported.');if(r.type==='svg'){if(typeof r.source!=='string'||r.source.length>8_000_000)throw Error('Missing or oversized reference SVG.');const clean=prepareSvgReference(r.source);r.data=svgImg(clean.safe);r.previewSanitized=true;}}return true;}
async function openFile(file){if(file.size>40_000_000)return toast('Project exceeds 40 MB import limit.');try{const obj=JSON.parse(await file.text());validateImported(obj);p=obj;step=0;selected=null;draftSelected=p.icons.map(x=>x.concept);draftCalibration=p.calibration.concepts.slice();modal=null;render();toast('Project reopened locally: '+p.manifest.name);}catch(e){toast('Cannot open project: '+e.message);}}
function confirmReset(){if(confirm('Create a fresh project? Save the current JSON first if you need it.')){p=freshProject();selected=null;draftSelected=['star','moon','book','archive','compare','evidence','uncertainty','branch'];draftCalibration=[];step=0;render();}}
function sampleSVG(icon){return iconSVG(icon,'balanced',{strokeColor:'#314b68',accentColor:'#c06c75',strokeWidth:3,linecap:'round',linejoin:'round',padding:6,background:'#fffcf4'});}
function demo(){if(p.history.length||p.icons.length||p.references.length){if(!confirm('Load a self-contained example? Your current unsaved work will be replaced.'))return;}p=freshProject();p.manifest.name='Constellation Archive · demonstration';p.references=['star','moon','book','archive'].map(c=>{let source=sampleSVG(c);return {id:uid('ref'),name:c+'-reference.svg',size:source.length,mediaType:'image/svg+xml',type:'svg',data:svgImg(source),source,stats:analyzeSvg(source),attribution:'Locally constructed demo reference; no external copyright claim',usage:'Demonstration',date:now(),notes:'Deterministic example reference.'};});extractDNA();Object.values(p.styleDNA.rules).forEach(r=>{if(r.source==='Observed SVG attributes')r.status='approved';});p.calibration.concepts=['star','book','compare','branch'];p.calibration.variants={};p.calibration.approved=true;p.calibration.approvedAt=now();draftSelected=['star','moon','book','archive','compare','evidence','uncertainty','branch'];p.icons=draftSelected.map(c=>makeAsset(c));p.icons.forEach(a=>{a.status='approved';a.semanticReviewed=true;a.semanticNotes='Demo sample: manually marked as reviewed for tutorial only; actual user validation is still required.';});record('demo.seed','Seeded an offline example with four original vector references and eight recipe icons. No external model, image generator, or uploaded data.',p.icons.map(a=>a.id));selected=p.icons[0].id;step=0;audit();step=0;render();toast('Example loaded. Try editing a Style DNA rule, saving JSON, and reopening.');}
function saveAssetField(a,field,v){snapshot('Before asset change: '+a.label);if(field==='exception')a.exception=v.trim()?{reason:v.trim(),author:'local user',date:now(),scope:a.id,validity:'Until reconsidered after related rules change'}:null;else a[field]=v;a.updated=now();record('asset.refine',`Updated ${field} for ${a.label}.`,[a.id]);render();}
document.addEventListener('click',e=>{let b=e.target.closest('[data-go],[data-act]');if(!b)return;let g=b.dataset.go;if(g!==undefined){step=Number(g);render();return;}let act=b.dataset.act,id=b.dataset.id,a=p.icons.find(x=>x.id===id);switch(act){case 'new':confirmReset();break;case 'demo':demo();break;case 'open':$('#openfile').click();break;case 'pickrefs':$('#reffile').click();break;case 'save':saveJSON();break;case 'export':exportZIP();break;case 'extract':extractDNA();break;case 'removeref':if(confirm('Remove this reference? Its source will no longer be embedded in future archives. A snapshot is preserved.')){snapshot('Before removing reference');p.references=p.references.filter(x=>x.id!==id);record('reference.remove','Removed reference by user request.',[id]);render();}break;case 'rulestatus':{let r=p.styleDNA.rules[id];snapshot('Before changing rule status');r.status=b.dataset.value;r.updated=now();record('dna.status',`${id} status set to ${r.status}.`,[id]);render();break;}case 'savegrammar':snapshot('Before grammar edit');p.symbolicGrammar.enabled=$('#grammarenabled').checked;p.symbolicGrammar.notes=$('#grammarnotes').value;record('grammar.update','Updated optional manually edited grammar description.');render();break;case 'proposecal':proposeCalibration();break;case 'approvecal':p.calibration.notes=$('#calnotes').value;approveCalibration();break;case 'calvariant':snapshot('Before calibration variant');p.calibration.variants[id]=b.dataset.value;p.calibration.approved=false;record('calibration.variant',`Selected ${b.dataset.value} for ${id}.`,[id]);render();break;case 'generate':createBatch(false);break;case 'overridecal':modal=null;record('calibration.override','User explicitly bypassed unapproved calibration for exploratory batch.');createBatch(true);break;case 'closemodal':modal=null;pendingRule=null;render();break;case 'selecticon':selected=id;render();break;case 'deselect':selected=null;render();break;case 'variant':if(a&&!a.locked&&!a.manualOverride){snapshot('Before variant change');a.ancestry.push({timestamp:now(),action:'variant changed',previous:a.sourceSvg});a.variant=b.dataset.value;a.sourceSvg=iconSVG(a.concept,a.variant);a.status='draft';record('asset.variant','Set recipe variant to '+a.variant,[id]);render();}break;case 'approveasset':if(a){snapshot('Before approving '+a.label);a.status='approved';a.updated=now();record('asset.approve','User approved rendered asset. Semantic review status: '+a.semanticReviewed,[id]);render();}break;case 'downloadsvg':if(a){download(fileSlug(a.label)+'.svg',a.sourceSvg,'image/svg+xml');toast('Exported editable SVG source.');}break;case 'savesvg':if(a)editAssetSVG(a,$('#svgeditor').value);break;case 'rejoin':modal={type:'rejoin',id};render();break;case 'commitrejoin':{let t=p.icons.find(x=>x.id===id);if(t){snapshot('Before rejoining DNA');t.ancestry.push({timestamp:now(),action:'rejoin',previous:t.sourceSvg});t.manualOverride=false;t.locked=false;t.pinned=false;t.sourceSvg=iconSVG(t.concept,t.variant);t.status='draft';record('asset.rejoin','Rejoined shared Style DNA.',[id]);}modal=null;render();break;}case 'audit':audit();break;case 'snapshot':snapshot('User-created recovery point');render();toast('Recovery snapshot created');break;case 'restore':modal={type:'restore',id};render();break;case 'commitrestore':{const ss=p.snapshots.find(x=>x.id===id);if(ss){let current=clone(p);let restored=clone(ss.state);restored.snapshots=[...current.snapshots,{id:uid('snap'),timestamp:now(),reason:'Before restore',revision:current.manifest.revision,state:(()=>{let r=clone(current);delete r.snapshots;return r;})()}];p=restored;record('snapshot.restore','Restored selected prior project state.',[id]);selected=null;}modal=null;render();break;}case 'commitrule':commitRule();break;}});
document.addEventListener('change',e=>{const t=e.target;if(t.dataset.rule){updateRule(t.dataset.rule,t.value);return;}if(t.dataset.pick){let x=t.dataset.pick;draftSelected=t.checked?[...new Set([...draftSelected,x])]:draftSelected.filter(a=>a!==x);return;}if(t.dataset.calpick){snapshot('Before calibration concept selection');let x=t.dataset.calpick;let ar=p.calibration.concepts;let found=ar.includes(x);if(t.checked&&!found)ar.push(x);if(!t.checked&&found)p.calibration.concepts=ar.filter(y=>y!==x);p.calibration.approved=false;record('calibration.selection','User '+(t.checked?'added ':'removed ')+x+' from stress-test concepts.',[x]);return;}if(t.dataset.prop){if(!pendingRule)return;t.checked?pendingRule.approved.add(t.dataset.prop):pendingRule.approved.delete(t.dataset.prop);return;}if(t.dataset.refnote){let r=p.references.find(x=>x.id===t.dataset.refnote);if(r){snapshot('Before attribution update');r.attribution=t.value;record('reference.attribution','Updated user-supplied reference attribution.',[r.id]);}return;}if(t.dataset.field==='project-name'){p.manifest.name=t.value;record('project.rename','Renamed project.');return;}if(t.dataset.assetfield){let a=p.icons.find(x=>x.id===t.dataset.id);if(a)saveAssetField(a,t.dataset.assetfield,t.value);return;}if(t.dataset.assetcheck){let a=p.icons.find(x=>x.id===t.dataset.id);if(a)saveAssetField(a,t.dataset.assetcheck,t.checked);return;}});
$('#openfile').addEventListener('change',async e=>{if(e.target.files[0])await openFile(e.target.files[0]);e.target.value='';});$('#reffile').addEventListener('change',async e=>{if(e.target.files.length)await importReferences(e.target.files);e.target.value='';});document.addEventListener('dragover',e=>{if(e.target.closest('#dropzone')){e.preventDefault();e.target.closest('#dropzone').classList.add('drag');}});document.addEventListener('drop',e=>{let z=e.target.closest('#dropzone');if(z){e.preventDefault();z.classList.remove('drag');importReferences(e.dataTransfer.files);}});window.addEventListener('beforeunload',e=>{if(p.history.length){e.preventDefault();e.returnValue='';}});render();